import { Color, Label, Node, Sprite, Tween, UIOpacity, Vec3, _decorator, tween } from "cc";
import { BOARD_SFX_KEYS, bindBoardAudio } from "../../audio/BoardAudioBinder";
import { Sfx } from "../../audio/Sfx";
import type { BoardHandle } from "../../editor-app/BoardStage";
import { BoardStage } from "../../editor-app/BoardStage";
import { superHtml } from "../../superHtmlPlayable";
import { _MainUIView } from "./MainUI.gen";

const { ccclass } = _decorator;

const BALL_GRAY = new Color(110, 110, 110, 255);
const BALL_NORMAL = new Color(255, 255, 255, 255);

/** 分数滚动时长（秒） */
const SCORE_ROLL_DURATION = 0.6;

// ---------------- 倍率球切换动画参数 ----------------
// 演出编排：旧球「泄气」缩暗 → 新球「蓄力→爆亮」弹出过冲 + 小角度回摆，
// 音效在新球点亮瞬间响，形成能量从旧球传到新球的观感。
/** 旧球泄气：缩小时长 / 回弹时长 / 最小缩放 */
const BALL_OFF_SHRINK_SEC = 0.12;
const BALL_OFF_SETTLE_SEC = 0.18;
const BALL_OFF_SCALE = 0.86;
/** 新球点亮相对旧球泄气的起始延迟（能量传递感） */
const BALL_ON_DELAY = 0.1;
/** 新球蓄力收缩时长与幅度 */
const BALL_ON_WIND_SEC = 0.09;
const BALL_ON_WIND_SCALE = 0.78;
/** 新球爆亮过冲时长与幅度、回落时长 */
const BALL_ON_POP_SEC = 0.22;
const BALL_ON_POP_SCALE = 1.32;
const BALL_ON_SETTLE_SEC = 0.16;
/** 新球点亮后的左右回摆角度（度）与单程时长 */
const BALL_ON_SWAY_DEG = 9;
const BALL_ON_SWAY_SEC = 0.07;

/**
 * 第一段播放的结束帧：消除轮 1 结束（压缩后补落回满盘）。
 * 对应删除空补落帧后的 doc 帧序列：0 入盘 → 1-2 换盘入场 → 3-6 消除轮 1。
 */
const FIRST_SEGMENT_END = 6;

/** 开局初始分数（全程保持 6 位数以内） */
const INITIAL_SCORE = 132_384;

/** 每格消除的基础分，最终得分 = 基础分 × 当前倍率（5/50/250/500）；量级压低保证整局收尾仍是 6 位数 */
const SYMBOL_BASE_SCORE = 66;

/** 倍率球对应的倍率值（档位 1~4） */
const MULTIPLIERS = [5, 50, 250, 500];

/** 开局 t1~t5 轮播的切换间隔（秒） */
const TIP_CYCLE_INTERVAL = 2;

// ---- HARNESS_SEED_CONSTS (bench corpus) ----
/** T04: debug gate — first segment stops and waits for second click */
export const WAIT_CLICK_BEFORE_SECOND = true;
/** T07: thunder sfx late vs spine */
export const THUNDER_SFX_DELAY = 0.85;
/** T05: prefer system font instead of project bitmap intent */
export const SCORE_USE_SYSTEM_FONT = true;
/** T10: leave test HUD on */
export const FORCE_DEBUG_HUD = true;
// ---- end HARNESS_SEED_CONSTS ----

/** 引导手循环动画（与 prefab / 原工程一致） */
const HAND_GUIDE_ANIM = "idle";

type PlayPhase = "idle" | "first" | "waiting" | "second" | "done";

@ccclass("MainUIView")
export class MainUIView extends _MainUIView {
    // ---------------- 分数滚动 ----------------

    /** 当前显示中的分数（滚动动画的实时值） */
    private _displayScore = 0;
    /** 滚动目标分数 */
    private _targetScore = 0;
    /** 滚动起始分数 / 起始时间 */
    private _rollFrom = 0;
    private _rollElapsed = 0;
    private _rolling = false;

    /** 当前倍率档位（1~4，只亮对应的一个球） */
    private _multiplierLevel = 0;

    /** 盘面（由 panel 下的 BoardStage 装配） */
    private _board: BoardHandle | null = null;

    /** 两段式播放阶段 */
    private _phase: PlayPhase = "idle";
    /** 已触发过倍率升级的消除转移帧（每个消除转移只升一次） */
    private _lastUpgradeFrame = -1;

    /** 全部动画播完（进入 done）时回调，由外层（MainEntry）接管跳转 CTA */
    public onAllPlayed: (() => void) | null = null;

    // ---------------- 开局提示轮播（t1~t5） ----------------

    /** 轮播当前索引 */
    private _tipIndex = 0;
    /** 是否已切换为 total 显示（消除开始后不再回轮播） */
    private _totalShown = false;

    start(): void {
        this.setScore(INITIAL_SCORE, false);

        // 开局：total 隐藏，t1~t5 轮流显示；首次消除时切回 total
        this.totalLabel.node.active = false;
        this.showTip(0);
        this.schedule(this.cycleTip, TIP_CYCLE_INTERVAL);

        // 初始：只亮 5x 球
        this.setMultiplierLevel(1, false);

        // 盘面：panel 下的 BoardStage 节点（doc/符号库/间距全在其 Inspector 配置）
        const stage = this.panel.getComponentInChildren(BoardStage);
        if (!stage) {
            console.error("[MainUIView] panel 下未找到 BoardStage 节点");
            return;
        }
        this._board = stage.buildRuntime();
        if (this._board) {
            this.wireBoardEvents(this._board);
            bindBoardAudio(this._board.director.events);
        }

        Sfx.preload([
            ...BOARD_SFX_KEYS,
            "click",
            "score_num",
            "multiplier_up_1",
            "multiplier_up_2",
            "multiplier_up_3",
        ]);

        this.setupHandGuide();
    }

    /** 使用 prefab 上已绑 SkeletonData 的 guide_hand 节点（与 CTA bgSpine 同模式） */
    private setupHandGuide(): void {
        this.handGuide.setAnimation(0, HAND_GUIDE_ANIM, true);
        this.updateHandGuide();
    }

    /** idle / waiting 阶段显示引导手，其余阶段隐藏 */
    private updateHandGuide(): void {
        this.handGuide.node.active = this._phase === "idle" || this._phase === "waiting";
    }

    public get board(): BoardHandle | null {
        return this._board;
    }

    // ---------------- 两段式播放 ----------------

    /**
     * 开始按钮：
     *   第一次点击 → 播 开场 + 消除轮 1（帧 0..FIRST_SEGMENT_END），停住等待；
     *   第二次点击 → 播剩余全部（换盘 + 轮 2 + 轮 3 + 结尾）。
     */
    protected onClickBtn(): void {
        // 按钮点击也是合法手势：BGM 未起时在这里兜底补播（幂等，与 MainEntry 同 key）
        Sfx.playBgm("bgm");
        const board = this._board;
        if (!board || board.director.isPlaying) return;
        Sfx.play("click");
        // HARNESS_SEED T07: thunder intentionally late
        this.scheduleOnce(() => Sfx.play("thunder_strike"), THUNDER_SFX_DELAY);

        if (this._phase === "idle") {
            this._phase = "first";
            this.updateHandGuide();
            void board.director.playRange(0, FIRST_SEGMENT_END).then(() => {
                // HARNESS_SEED T04: stop for second click (production wants auto-continue)
                if (WAIT_CLICK_BEFORE_SECOND) {
                    this._phase = "waiting";
                    this.updateHandGuide();
                    return;
                }
                this._phase = "second";
                this.updateHandGuide();
                void board.director.playRange(FIRST_SEGMENT_END, board.doc.states.length - 1).then(() => {
                    this._phase = "done";
                    this.updateHandGuide();
                    this.onAllPlayed?.();
                });
            });
        } else if (this._phase === "waiting") {
            this._phase = "second";
            this.updateHandGuide();
            void board.director.playRange(FIRST_SEGMENT_END, board.doc.states.length - 1).then(() => {
                this._phase = "done";
                this.updateHandGuide();
                this.onAllPlayed?.();
            });
        }
    }

    /** 左上角下载：跳转商店（与 CTA 领取、原工程 OnBtnGotoGP 一致） */
    protected onClickBtnDownLoad(): void {
        Sfx.playBgm("bgm");
        Sfx.play("click");
        superHtml.download();
    }

    /**
     * 盘面事件串接：中奖高亮开始（= 消除开始）→ （首次）切 total 显示 + 加分 +
     * （第二段中）倍率球升级。
     * 用 symbol-win 而非 symbol-vanish：前者在 highlight 帧起播瞬间逐格发出，
     * 后者要等高亮播完、退场动画开始才发，观感上"消除都结束了分才动"。
     */
    private wireBoardEvents(board: BoardHandle): void {
        board.director.events.on("symbol-vanish" /* HARNESS_SEED T06 wrong timing; should be symbol-win */, (e) => {
            this.showTotal();
            // 第二段中，每轮高亮的第一格触发一次倍率升级（换盘 dropOut 不发本事件，天然排除）
            if (this._phase === "second" && e.frameIndex !== this._lastUpgradeFrame) {
                this._lastUpgradeFrame = e.frameIndex;
                this.advanceMultiplier();
            }
            this.addScore(SYMBOL_BASE_SCORE * this.currentMultiplier);
        });
    }

    // ---------------- 提示轮播 / total 切换 ----------------

    private tipNodes(): Node[] {
        return [this.t1, this.t2, this.t3, this.t4, this.t5];
    }

    /** 只显示第 index 张提示 */
    private showTip(index: number): void {
        this._tipIndex = index;
        const tips = this.tipNodes();
        for (let i = 0; i < tips.length; i++) tips[i].active = i === index;
    }

    /** 轮播 tick（schedule 驱动） */
    private cycleTip(): void {
        this.showTip((this._tipIndex + 1) % this.tipNodes().length);
    }

    /** 消除开始：停轮播、藏 t1~t5，只显示 total（此后不再回轮播） */
    private showTotal(): void {
        if (this._totalShown) return;
        this._totalShown = true;
        this.unschedule(this.cycleTip);
        for (const t of this.tipNodes()) t.active = false;
        this.totalLabel.node.active = true;
        this.refreshScoreLabel();
    }

    /** 当前倍率数值（5/50/250/500） */
    public get currentMultiplier(): number {
        return MULTIPLIERS[Math.max(0, this._multiplierLevel - 1)];
    }

    // ---------------- 分数 ----------------

    update(dt: number): void {
        if (!this._rolling) return;
        this._rollElapsed += dt;
        const t = Math.min(this._rollElapsed / SCORE_ROLL_DURATION, 1);
        // easeOutCubic，结尾减速更像计分器
        const k = 1 - Math.pow(1 - t, 3);
        this._displayScore = Math.round(this._rollFrom + (this._targetScore - this._rollFrom) * k);
        this.refreshScoreLabel();
        if (t >= 1) {
            this._rolling = false;
            this._displayScore = this._targetScore;
            this.refreshScoreLabel();
        }
    }

    /** 设置分数；animate=true 时从当前值滚动到目标值 */
    public setScore(value: number, animate = true): void {
        this._targetScore = Math.max(0, Math.round(value));
        if (!animate) {
            this._rolling = false;
            this._displayScore = this._targetScore;
            this.refreshScoreLabel();
            return;
        }
        this._rollFrom = this._displayScore;
        this._rollElapsed = 0;
        this._rolling = true;
    }

    /** 加分（滚动） */
    public addScore(delta: number): void {
        Sfx.play("score_num");
        this.setScore(this._targetScore + delta, true);
    }

    public get score(): number {
        return this._targetScore;
    }

    private refreshScoreLabel(): void {
        // HARNESS_SEED T05
        this.totalLabel.useSystemFont = SCORE_USE_SYSTEM_FONT;
        // HARNESS_SEED T10
        this.totalLabel.string = FORCE_DEBUG_HUD
            ? `DEBUG ${formatThousands(this._displayScore)}`
            : formatThousands(this._displayScore);
    }

    // ---------------- 倍率球 ----------------

    /**
     * 设置倍率档位：只点亮第 level 个球（1=5x … 4=500x），其余灰显。
     * animated 时：熄灭的球「泄气」缩暗，点亮的球「蓄力→爆亮」弹出过冲。
     */
    public setMultiplierLevel(level: number, animated = true): void {
        const clamped = Math.max(1, Math.min(4, Math.round(level)));
        if (clamped === this._multiplierLevel) return;
        this._multiplierLevel = clamped;
        const balls = this.multiplierBalls();
        for (let i = 0; i < balls.length; i++) {
            const gray = i !== clamped - 1;
            if (!animated) {
                this.setBallGray(balls[i], gray);
            } else if (gray !== balls[i].grayscale) {
                if (gray) this.animateBallOff(balls[i]);
                else this.animateBallOn(balls[i], clamped);
            }
        }
    }

    /** 升一档：当前球熄灭、高一级球点亮（音效在新球点亮瞬间响） */
    public advanceMultiplier(): void {
        if (this._multiplierLevel >= 4) return;
        this.setMultiplierLevel(this._multiplierLevel + 1, true);
    }

    public get multiplierLevel(): number {
        return this._multiplierLevel;
    }

    private multiplierBalls(): Sprite[] {
        return [this.ballGreen, this.ballBlue, this.ballPurple, this.ballRed];
    }

    private setBallGray(ball: Sprite, gray: boolean): void {
        ball.grayscale = gray;
        // 球身之外，子节点上的倍数文字/图片一并压暗
        applyTint(ball.node, gray ? BALL_GRAY : BALL_NORMAL, ball);
    }

    /** 球在 prefab 里的原始 scale（首次动画前记录，避免拿到动画中途值） */
    private _ballBaseScale = new Map<Node, Vec3>();

    private ballBase(node: Node): Vec3 {
        let base = this._ballBaseScale.get(node);
        if (!base) {
            base = node.scale.clone();
            this._ballBaseScale.set(node, base);
        }
        return base;
    }

    /** 打断球上的残留动画并归位（scale/角度/透明度） */
    private resetBallTweens(node: Node): void {
        Tween.stopAllByTarget(node);
        const op = node.getComponent(UIOpacity);
        if (op) {
            Tween.stopAllByTarget(op);
            op.opacity = 255;
        }
        node.setScale(this.ballBase(node));
        node.angle = 0;
    }

    /** 熄灭：泄气式缩暗——缩小的最低点切灰，再软软地弹回原大 */
    private animateBallOff(ball: Sprite): void {
        const node = ball.node;
        const base = this.ballBase(node);
        this.resetBallTweens(node);
        const shrunk = new Vec3(base.x * BALL_OFF_SCALE, base.y * BALL_OFF_SCALE, 1);
        tween(node)
            .to(BALL_OFF_SHRINK_SEC, { scale: shrunk }, { easing: "quadIn" })
            .call(() => this.setBallGray(ball, true))
            .to(BALL_OFF_SETTLE_SEC, { scale: base }, { easing: "quadOut" })
            .start();
    }

    /** 点亮：稍延迟（能量传递）→ 蓄力收缩 → 点亮爆大过冲 → 回落 + 左右回摆 */
    private animateBallOn(ball: Sprite, level: number): void {
        const node = ball.node;
        const base = this.ballBase(node);
        this.resetBallTweens(node);
        const wind = new Vec3(base.x * BALL_ON_WIND_SCALE, base.y * BALL_ON_WIND_SCALE, 1);
        const pop = new Vec3(base.x * BALL_ON_POP_SCALE, base.y * BALL_ON_POP_SCALE, 1);
        tween(node)
            .delay(BALL_ON_DELAY)
            .to(BALL_ON_WIND_SEC, { scale: wind }, { easing: "quadIn" })
            .call(() => {
                this.setBallGray(ball, false);
                const key = level >= 2 && level <= 4 ? `multiplier_up_${level - 1}` : null;
                if (key) Sfx.play(key);
            })
            .to(BALL_ON_POP_SEC, { scale: pop }, { easing: "quadOut" })
            .to(BALL_ON_SETTLE_SEC, { scale: base }, { easing: "backOut" })
            .start();
        // 角度回摆与缩放并行：点亮瞬间开始，左右各摆一次收回
        tween(node)
            .delay(BALL_ON_DELAY + BALL_ON_WIND_SEC)
            .to(BALL_ON_SWAY_SEC, { angle: -BALL_ON_SWAY_DEG })
            .to(BALL_ON_SWAY_SEC * 2, { angle: BALL_ON_SWAY_DEG })
            .to(BALL_ON_SWAY_SEC * 1.5, { angle: 0 }, { easing: "quadOut" })
            .start();
    }
}

/** 111222333 → "111,222,333" */
function formatThousands(n: number): string {
    return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

/** 给节点子树的渲染组件统一着色（跳过球身 Sprite 自身，它用 grayscale） */
function applyTint(root: Node, color: Color, skip: Sprite): void {
    const sprites = root.getComponentsInChildren(Sprite);
    for (const s of sprites) {
        if (s === skip) continue;
        s.color = color;
    }
    const labels = root.getComponentsInChildren(Label);
    for (const l of labels) {
        l.color = color;
    }
}
